router = APIRouter()

@router.get("/info")
async def get_models_info():
    """Get information about loaded models"""
    try:
        return {
            "device": "cuda" if torch.cuda.is_available() else "cpu",
            "cuda_available": torch.cuda.is_available(),
            "torch_version": torch.__version__,
            "models": {
                "image_generator": "Stable Diffusion v1.5",
                "3d_generator": "Point-E",
                "mesh_reconstructor": "Custom (Convex Hull / Poisson)",
            },
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post("/unload")
async def unload_models():
    """Unload models to free VRAM"""
    try:
        from routes.generation import image_gen, point_e_gen

        if image_gen:
            image_gen.unload_model()
        if point_e_gen:
            point_e_gen.unload_model()

        torch.cuda.empty_cache()

        return {"status": "success", "message": "Models unloaded"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

