import React, { useState } from 'react'
import axios from 'axios'

export function TextGenerator({ onGenerate }) {
  const [prompt, setPrompt] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  const handleGenerate = async (e) => {
    e.preventDefault()
    if (!prompt.trim()) return

    setLoading(true)
    setError(null)

    try {
      const formData = new FormData()
      formData.append('prompt', prompt)

      const response = await axios.post('/api/generate/from-text', formData)
      onGenerate(response.data.model_file)
    } catch (err) {
      setError(err.response?.data?.detail || 'Generation failed')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="generator-panel">
      <h2>Generate from Text</h2>
      <form onSubmit={handleGenerate}>
        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe the 3D model you want to create..."
          className="prompt-input"
          rows="4"
        />
        <button 
          type="submit" 
          disabled={loading}
          className="generate-btn"
        >
          {loading ? 'Generating...' : 'Generate 3D Model'}
        </button>
      </form>

      {error && <div className="error-message">{error}</div>}

      <div className="examples">
        <h3>Example Prompts:</h3>
        <ul>
          <li>"A detailed Warhammer 40k Space Marine with bolter"</li>
          <li>"A sci-fi robot with intricate details"</li>
          <li>"A fantasy dragon with wings"</li>
        </ul>
      </div>
    </div>
  )
}

