import React, { useEffect, useRef } from 'react'
import * as THREE from 'three'
import axios from 'axios'

export function ModelViewer({ modelFile }) {
  const containerRef = useRef(null)
  const sceneRef = useRef(null)

  useEffect(() => {
    if (!containerRef.current || !modelFile) return

    // Initialize Three.js scene
    const scene = new THREE.Scene()
    const camera = new THREE.PerspectiveCamera(
      75,
      containerRef.current.clientWidth / containerRef.current.clientHeight,
      0.1,
      1000
    )
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })

    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight)
    renderer.setClearColor(0x1a1a1a)
    containerRef.current.appendChild(renderer.domElement)

    camera.position.z = 5

    // Add lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5)
    scene.add(ambientLight)

    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8)
    directionalLight.position.set(5, 5, 5)
    scene.add(directionalLight)

    // Load STL file
    loadSTL(modelFile, scene)

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate)

      if (scene.children.length > 2) {
        const mesh = scene.children[2]
        mesh.rotation.x += 0.005
        mesh.rotation.y += 0.01
      }

      renderer.render(scene, camera)
    }
    animate()

    // Handle window resize
    const handleResize = () => {
      const width = containerRef.current.clientWidth
      const height = containerRef.current.clientHeight
      camera.aspect = width / height
      camera.updateProjectionMatrix()
      renderer.setSize(width, height)
    }

    window.addEventListener('resize', handleResize)

    sceneRef.current = scene

    return () => {
      window.removeEventListener('resize', handleResize)
      if (containerRef.current && containerRef.current.contains(renderer.domElement)) {
        containerRef.current.removeChild(renderer.domElement)
      }
    }
  }, [modelFile])

  const loadSTL = async (filename, scene) => {
    try {
      // For simplicity, we'll create a placeholder mesh
      // In production, you'd use a proper STL loader
      const geometry = new THREE.IcosahedronGeometry(2, 4)
      const material = new THREE.MeshStandardMaterial({
        color: 0x2196f3,
        metalness: 0.5,
        roughness: 0.5
      })
      const mesh = new THREE.Mesh(geometry, material)
      scene.add(mesh)
    } catch (err) {
      console.error('Error loading STL:', err)
    }
  }

  const handleDownload = async () => {
    try {
      const response = await axios.get(`/api/generate/download/${modelFile}`, {
        responseType: 'blob'
      })
      const url = window.URL.createObjectURL(new Blob([response.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', modelFile)
      document.body.appendChild(link)
      link.click()
      link.parentElement.removeChild(link)
    } catch (err) {
      console.error('Download failed:', err)
    }
  }

  return (
    <div className="model-viewer">
      <h2>3D Model Preview</h2>
      <div ref={containerRef} className="viewer-container" />
      <div className="viewer-controls">
        <button onClick={handleDownload} className="download-btn">
          Download STL
        </button>
      </div>
    </div>
  )
}

