import React, { useState, useEffect } from 'react'
import axios from 'axios'

export function TrainingPanel() {
  const [examples, setExamples] = useState([])
  const [status, setStatus] = useState(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    fetchStatus()
    scanExamples()
  }, [])

  const fetchStatus = async () => {
    try {
      const response = await axios.get('/api/train/status')
      setStatus(response.data)
    } catch (err) {
      console.error('Error fetching status:', err)
    }
  }

  const scanExamples = async () => {
    try {
      const response = await axios.post('/api/train/scan-examples')
      setExamples(response.data.examples)
    } catch (err) {
      console.error('Error scanning examples:', err)
    }
  }

  const handleProcess = async () => {
    setLoading(true)
    try {
      await axios.post('/api/train/process-examples')
      fetchStatus()
      alert('Examples processed successfully!')
    } catch (err) {
      alert('Error processing examples: ' + err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleFineTune = async () => {
    setLoading(true)
    try {
      const response = await axios.post('/api/train/fine-tune')
      alert('Fine-tuning started: ' + response.data.message)
      fetchStatus()
    } catch (err) {
      alert('Error starting fine-tune: ' + err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="training-panel">
      <h2>Model Training</h2>

      {status && (
        <div className="status-info">
          <p>Status: <strong>{status.status}</strong></p>
          <p>Processed Examples: <strong>{status.processed_examples}</strong></p>
          <p>Device: <strong>{status.device}</strong></p>
        </div>
      )}

      <div className="examples-section">
        <h3>Training Examples ({examples.length})</h3>
        <div className="examples-list">
          {examples.map((example) => (
            <div key={example.filename} className="example-card">
              <h4>{example.filename}</h4>
              <p>Vertices: {example.info.vertices_count}</p>
              <p>Faces: {example.info.faces_count}</p>
              <p>Volume: {example.info.volume.toFixed(2)}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="training-actions">
        <button 
          onClick={handleProcess}
          disabled={loading || examples.length === 0}
          className="action-btn primary"
        >
          {loading ? 'Processing...' : 'Process Examples'}
        </button>
        <button 
          onClick={handleFineTune}
          disabled={loading}
          className="action-btn secondary"
        >
          {loading ? 'Tuning...' : 'Fine-tune Models'}
        </button>
      </div>
    </div>
  )
}

