* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: #0a0a0a;
  color: #ffffff;
}

#root {
  width: 100%;
  height: 100vh;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.app-header {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  padding: 20px;
  text-align: center;
  border-bottom: 2px solid #764ba2;
}

.app-header h1 {
  font-size: 2.5rem;
  margin-bottom: 5px;
}

.app-header p {
  font-size: 1rem;
  opacity: 0.9;
}

.app-container {
  display: flex;
  flex: 1;
  overflow: hidden;
}

.tab-nav {
  display: flex;
  flex-direction: column;
  width: 200px;
  background: #1a1a1a;
  border-right: 2px solid #333;
  padding: 20px 0;
}

.tab {
  padding: 15px 20px;
  border: none;
  background: transparent;
  color: #888;
  cursor: pointer;
  text-align: left;
  font-size: 1rem;
  transition: all 0.3s;
  border-left: 3px solid transparent;
}

.tab:hover {
  color: #fff;
  background: #2a2a2a;
}

.tab.active {
  color: #667eea;
  border-left-color: #667eea;
  background: #222;
}

.content {
  flex: 1;
  display: flex;
  overflow: hidden;
}

.input-panel {
  flex: 1;
  padding: 30px;
  overflow-y: auto;
  border-right: 2px solid #333;
  max-width: 500px;
}

.viewer-panel {
  flex: 2;
  padding: 30px;
  overflow: hidden;
}

/* Generator Panel */
.generator-panel {
  background: #1a1a1a;
  border: 1px solid #333;
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 20px;
}

.generator-panel h2 {
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.prompt-input {
  width: 100%;
  padding: 12px;
  border: 1px solid #444;
  border-radius: 6px;
  background: #0a0a0a;
  color: #fff;
  font-size: 1rem;
  resize: vertical;
  margin-bottom: 15px;
}

.file-upload {
  border: 2px dashed #667eea;
  border-radius: 6px;
  padding: 20px;
  text-align: center;
  margin-bottom: 15px;
  background: #0a0a0a;
}

.file-input {
  display: block;
  width: 100%;
  margin-bottom: 10px;
}

.preview-image {
  max-width: 100%;
  max-height: 200px;
  border-radius: 6px;
}

.generate-btn, .action-btn, .download-btn {
  width: 100%;
  padding: 12px;
