import React, { useEffect, useRef, useState } from 'react'
import * as THREE from 'three'
import axios from 'axios'

// Simple STL loader
const STLLoader = () => {
  const parse = (arrayBuffer) => {
    const view = new DataView(arrayBuffer)
    const isASCII = isASCIISTL(arrayBuffer)

    if (isASCII) {
      return parseASCII(new TextDecoder().decode(arrayBuffer))
    } else {
      return parseBinary(view)
    }
  }

  const isASCIISTL = (arrayBuffer) => {
    const view = new Uint8Array(arrayBuffer)
    const header = new TextDecoder().decode(view.slice(0, 5))
    return header === 'solid'
  }

  const parseBinary = (view) => {
    const faces = view.getUint32(80, true)
    const geometry = new THREE.BufferGeometry()
    const vertices = []
    const normals = []

    let offset = 84
    for (let i = 0; i < faces; i++) {
      const nx = view.getFloat32(offset, true); offset += 4
      const ny = view.getFloat32(offset, true); offset += 4
      const nz = view.getFloat32(offset, true); offset += 4

      for (let j = 0; j < 3; j++) {
        vertices.push(
          view.getFloat32(offset, true); offset += 4,
          view.getFloat32(offset, true); offset += 4,
          view.getFloat32(offset, true); offset += 4
        )
        normals.push(nx, ny, nz)
      }
      offset += 2
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vertices), 3))
    geometry.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(normals), 3))
    geometry.computeBoundingBox()

    return geometry
  }

  const parseASCII = (text) => {
    const geometry = new THREE.BufferGeometry()
    const vertices = []
    const normals = []

    const patternNormal = /normal\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)/g
    const patternVertex = /vertex\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)\s+([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)/g

    let normalMatch
    let vertexMatch
    let normal = [0, 0, 0]

    while ((normalMatch = patternNormal.exec(text)) !== null) {
      normal = [parseFloat(normalMatch[1]), parseFloat(normalMatch[3]), parseFloat(normalMatch[5])]

      patternNormal.lastIndex = normalMatch.index

      for (let i = 0; i < 3; i++) {
        if ((vertexMatch = patternVertex.exec(text)) !== null) {
          vertices.push(parseFloat(vertexMatch[1]), parseFloat(vertexMatch[3]), parseFloat(vertexMatch[5]))
          normals.push(...normal)
        }
      }
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vertices), 3))
    geometry.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(normals), 3))
    geometry.computeBoundingBox()

    return geometry
  }

  return { parse }
}

export function ModelViewer({ modelFile }) {
  const containerRef = useRef(null)
  const sceneRef = useRef(null)
  const meshRef = useRef(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  useEffect(() => {
    if (!containerRef.current || !modelFile) return

    setLoading(true)
    setError(null)

    // Initialize Three.js scene
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0x1a1a1a)

    const camera = new THREE.PerspectiveCamera(
      75,
      containerRef.current.clientWidth / containerRef.current.clientHeight,
      0.1,
      1000
    )
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })

    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight)
    renderer.shadowMap.enabled = true
    containerRef.current.appendChild(renderer.domElement)

    camera.position.set(0, 0, 5)

    // Add lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6)
    scene.add(ambientLight)

    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8)
    directionalLight.position.set(10, 10, 10)
    directionalLight.castShadow = true
    scene.add(directionalLight)

    const pointLight = new THREE.PointLight(0x667eea, 0.5)
    pointLight.position.set(-10, 10, 5)
    scene.add(pointLight)

    // Load STL file
    loadSTL(modelFile, scene, camera, renderer)

    sceneRef.current = scene

    // Animation loop
    let animationId
    const animate = () => {
      animationId = requestAnimationFrame(animate)

      if (meshRef.current) {
        meshRef.current.rotation.x += 0.003
        meshRef.current.rotation.y += 0.005
      }

      renderer.render(scene, camera)
    }
    animate()

    // Handle window resize
    const handleResize = () => {
      if (!containerRef.current) return
      const width = containerRef.current.clientWidth
      const height = containerRef.current.clientHeight
      camera.aspect = width / height
      camera.updateProjectionMatrix()
      renderer.setSize(width, height)
    }

    window.addEventListener('resize', handleResize)

    return () => {
      window.removeEventListener('resize', handleResize)
      cancelAnimationFrame(animationId)
      if (containerRef.current && containerRef.current.contains(renderer.domElement)) {
        containerRef.current.removeChild(renderer.domElement)
      }
      renderer.dispose()
    }
  }, [modelFile])

  const loadSTL = async (filename, scene, camera, renderer) => {
    try {
      // Download the STL file
      const response = await axios.get(`/api/generate/download/${filename}`, {
        responseType: 'arraybuffer'
      })

      // Parse STL
      const loader = STLLoader()
      const geometry = loader.parse(response.data)

      // Center and scale geometry
      geometry.center()
      geometry.computeBoundingBox()
      const size = geometry.boundingBox.getSize(new THREE.Vector3())
      const maxDim = Math.max(size.x, size.y, size.z)
      const scale = 4 / maxDim
      geometry.scale(scale, scale, scale)

      // Create material and mesh
      const material = new THREE.MeshStandardMaterial({
        color: 0x667eea,
        metalness: 0.3,
        roughness: 0.4,
        flatShading: false
      })
      const mesh = new THREE.Mesh(geometry, material)
      mesh.castShadow = true
      mesh.receiveShadow = true

      scene.add(mesh)
      meshRef.current = mesh

      // Adjust camera
      const distance = maxDim / Math.tan((camera.fov * Math.PI) / 360)
      camera.position.z = distance
      camera.lookAt(mesh.position)

      setLoading(false)
    } catch (err) {
      console.error('Error loading STL:', err)
      setError('Failed to load 3D model')
      setLoading(false)

      // Show placeholder if loading fails
      const geometry = new THREE.IcosahedronGeometry(2, 4)
      const material = new THREE.MeshStandardMaterial({
        color: 0x2196f3,
        metalness: 0.5,
        roughness: 0.5
      })
      const mesh = new THREE.Mesh(geometry, material)
      scene.add(mesh)
      meshRef.current = mesh
    }
  }

  const handleDownload = async () => {
    try {
      const response = await axios.get(`/api/generate/download/${modelFile}`, {
        responseType: 'blob'
      })
      const url = window.URL.createObjectURL(new Blob([response.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', modelFile)
      document.body.appendChild(link)
      link.click()
      link.parentElement.removeChild(link)
      window.URL.revokeObjectURL(url)
    } catch (err) {
      console.error('Download failed:', err)
      setError('Download failed')
    }
  }

  return (
    <div className="model-viewer">
      <div className="viewer-header">
        <h2>3D Model Preview</h2>
        {loading && <span className="loading-indicator">Loading model...</span>}
      </div>
      <div ref={containerRef} className="viewer-container" />
      {error && <div className="error-message">{error}</div>}
      <div className="viewer-controls">
        <button onClick={handleDownload} className="download-btn">
          ⬇ Download STL
        </button>
      </div>
    </div>
  )
}

