import React, { useState } from 'react'
import { TextGenerator } from './components/TextGenerator'
import { ImageUploader } from './components/ImageUploader'
import { ModelViewer } from './components/ModelViewer'
import { TrainingPanel } from './components/TrainingPanel'
import { Landing } from './components/Landing'
import './App.css'

export default function App() {
  const [showApp, setShowApp] = useState(false)
  const [activeTab, setActiveTab] = useState('text')
  const [generatedModel, setGeneratedModel] = useState(null)

  if (!showApp) {
    return <Landing onGetStarted={() => setShowApp(true)} />
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="header-content">
          <div>
            <h1>3D Sculpting AI</h1>
            <p>Generate 3D models from text and images</p>
          </div>
          <button 
            className="home-btn"
            onClick={() => {
              setShowApp(false)
              setGeneratedModel(null)
              setActiveTab('text')
            }}
          >
            Home
          </button>
        </div>
      </header>

      <div className="app-container">
        <nav className="tab-nav">
          <button 
            className={`tab ${activeTab === 'text' ? 'active' : ''}`}
            onClick={() => setActiveTab('text')}
          >
            📝 Text to 3D
          </button>
          <button 
            className={`tab ${activeTab === 'image' ? 'active' : ''}`}
            onClick={() => setActiveTab('image')}
          >
            🖼️ Image to 3D
          </button>
          <button 
            className={`tab ${activeTab === 'training' ? 'active' : ''}`}
            onClick={() => setActiveTab('training')}
          >
            🎓 Training
          </button>
        </nav>

        <div className="content">
          <div className="input-panel">
            {activeTab === 'text' && (
              <TextGenerator onGenerate={setGeneratedModel} />
            )}
            {activeTab === 'image' && (
              <ImageUploader onGenerate={setGeneratedModel} />
            )}
            {activeTab === 'training' && (
              <TrainingPanel />
            )}
          </div>

          {generatedModel && (
            <div className="viewer-panel">
              <ModelViewer modelFile={generatedModel} />
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

