import { app, BrowserWindow, Menu } from 'electron'
import path from 'path'
import { fileURLToPath } from 'url'
import { spawn } from 'child_process'
import { existsSync } from 'fs'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

let mainWindow
let backendProcess

const isDev = process.env.NODE_ENV === 'development'
const backendPath = path.join(__dirname, '..', 'backend', 'main.py')

// Start backend process
function startBackend() {
  if (isDev) {
    // In development, assume backend is already running
    console.log('Development mode: assuming backend is running on port 8000')
    return
  }

  // In production, start the bundled backend
  if (existsSync(backendPath)) {
    console.log('Starting backend:', backendPath)
    backendProcess = spawn('python', [backendPath], {
      stdio: 'inherit',
      detached: true
    })

    backendProcess.on('error', (err) => {
      console.error('Failed to start backend:', err)
    })
  } else {
    console.warn('Backend not found at', backendPath)
  }
}

// Create window
function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 1000,
    minHeight: 700,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true
    },
    icon: path.join(__dirname, 'assets', 'icon.png')
  })

  const startUrl = isDev 
    ? 'http://localhost:5173'
    : `file://${path.join(__dirname, 'dist', 'index.html')}`

  mainWindow.loadURL(startUrl)

  if (isDev) {
    mainWindow.webContents.openDevTools()
  }

  mainWindow.on('closed', () => {
    mainWindow = null
  })

  // Create menu
  createMenu()
}

// Create application menu
function createMenu() {
  const template = [
    {
      label: 'File',
      submenu: [
        {
          label: 'Exit',
          accelerator: 'CmdOrCtrl+Q',
          click: () => {
            app.quit()
          }
        }
      ]
    },
    {
      label: 'Edit',
      submenu: [
        { role: 'undo' },
        { role: 'redo' },
        { type: 'separator' },
        { role: 'cut' },
        { role: 'copy' },
        { role: 'paste' }
      ]
    },
    {
      label: 'View',
      submenu: [
        { role: 'reload' },
        { role: 'forceReload' },
        { role: 'toggleDevTools' }
      ]
    }
  ]

  const menu = Menu.buildFromTemplate(template)
  Menu.setApplicationMenu(menu)
}

// App event handlers
app.on('ready', () => {
  startBackend()
  createWindow()
})

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit()
  }

  // Kill backend process
  if (backendProcess) {
    process.kill(-backendProcess.pid)
  }
})

app.on('activate', () => {
  if (mainWindow === null) {
    createWindow()
  }
})

